sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.activeSection = '';
  c.netsNumber = '';
  c.netsSearching = false;
  c.netsRecord = null;
  c.submitting = false;

  c.form = {
    short_description: '',
    notification_message: '',
    severity: 'medium',
    recipient_group: '',
    recipient_user: ''
  };

  c.showNets = function() {
    c.activeSection = 'nets';
    c.netsRecord = null;
    c.data.message = '';
    c.data.success = false;
  };

  c.showGeneral = function() {
    c.activeSection = 'general';
    c.data.message = '';
    c.data.success = false;
    c.data.formSaved = false;
  };

  c.searchNets = function() {
    if (!c.netsNumber) return;
    c.netsSearching = true;
    c.netsRecord = null;
    c.data.message = '';
    c.server.get({ action: 'searchNets', nets_number: c.netsNumber }).then(function(r) {
      c.data = r.data;
      c.netsRecord = r.data.netsRecord;
      c.netsSearching = false;
    }, function() {
      c.netsSearching = false;
    });
  };

  c.saveDraft = function() {
    c.submitForm('draft');
  };

  c.sendFlash = function() {
    c.submitForm('sent');
  };

  c.submitForm = function(status) {
    if (!c.form.short_description) return;
    c.submitting = true;
    c.server.get({
      action: 'saveGeneral',
      short_description: c.form.short_description,
      notification_message: c.form.notification_message,
      severity: c.form.severity,
      recipient_group: c.form.recipient_group,
      recipient_user: c.form.recipient_user,
      flash_status: status
    }).then(function(r) {
      c.data = r.data;
      c.submitting = false;
      if (r.data.success) {
        c.form = {
          short_description: '',
          notification_message: '',
          severity: 'medium',
          recipient_group: '',
          recipient_user: ''
        };
      }
    }, function() {
      c.submitting = false;
    });
  };

  c.getSeverityClass = function(severity) {
    if (!severity) return 'label-default';
    var s = severity.toLowerCase();
    if (s === 'critical') return 'label-danger';
    if (s === 'high') return 'label-warning';
    if (s === 'medium') return 'label-info';
    if (s === 'low') return 'label-success';
    return 'label-default';
  };
};

sp_widget.css:
.sp-card {
  display: flex;
  flex-direction: column;
  width: 100%;
  border: 1px solid $border-tertiary;
  border-radius: $border-radius-large;
  box-shadow: 0 1px 4px rgba($text-color, 0.07);
  background: $background-primary;
  overflow: hidden;
  margin-bottom: 0;
}
.sp-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  background: $background-primary;
  border-bottom: 1px solid $border-tertiary;
  min-height: 52px;
  flex-shrink: 0;
}
.sp-card-title {
  font-size: $font-size-large;
  font-weight: 600;
  color: $text-color;
  margin: 0;
}
.sp-card-icon {
  margin-right: 8px;
  color: $brand-primary;
  font-size: 16px;
}
.sp-card-body {
  padding: 24px;
  flex: 1 1 auto;
}
.sp-btn-group {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-top: 24px;
  flex-wrap: wrap;
}
.sp-btn-primary {
  height: 44px;
  padding: 0 20px;
  border-radius: $border-radius-base;
  font-size: $font-size-base;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: background 0.15s, box-shadow 0.15s;
  cursor: pointer;
  border: none;
  background: $brand-primary;
  color: $btn-primary-color;
  &:hover:not(:disabled) {
    background: $brand-primary-dark;
    box-shadow: 0 2px 8px rgba($brand-primary, 0.3);
    color: $btn-primary-color;
  }
  &:disabled {
    opacity: 0.55;
    cursor: not-allowed;
  }
}
.sp-btn-secondary {
  background: $background-primary;
  border: 1px solid $border-tertiary;
  color: $text-color;
  height: 44px;
  padding: 0 20px;
  border-radius: $border-radius-base;
  font-size: $font-size-base;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  &:hover {
    background: $background-secondary;
  }
}
.sp-input {
  height: $input-height-base;
  border: 1px solid $border-tertiary;
  border-radius: $border-radius-base;
  padding: 0 12px;
  font-size: $font-size-base;
  color: $text-color;
  background: $background-primary;
  transition: border-color 0.15s, box-shadow 0.15s;
  width: 100%;
  &:focus {
    border-color: $brand-primary;
    box-shadow: 0 0 0 3px rgba($brand-primary, 0.15);
    outline: none;
  }
}
.sp-textarea {
  border-radius: $border-radius-base;
  border: 1px solid $border-tertiary;
  padding: 12px;
  font-size: $font-size-base;
  resize: vertical;
  min-height: 100px;
  transition: border-color 0.15s;
  &:focus {
    border-color: $brand-primary;
    box-shadow: 0 0 0 3px rgba($brand-primary, 0.15);
    outline: none;
  }
}
.sp-nets-result {
  margin-top: 24px;
  padding: 16px;
  background: $background-secondary;
  border-radius: $border-radius-base;
  border: 1px solid $border-tertiary;
  dt {
    font-size: $font-size-small;
    color: $text-muted;
    margin-top: 8px;
  }
  dd {
    font-size: $font-size-base;
    color: $text-color;
    margin-left: 0;
    margin-bottom: 4px;
  }
}
.sp-detail-message {
  background: $background-primary;
  padding: 12px 16px;
  border-radius: $border-radius-base;
  font-size: $font-size-base;
  line-height: 1.6;
  margin-top: 4px;
  border: 1px solid $border-tertiary;
}
.sp-back-btn {
  margin-top: 24px;
}
@keyframes sp-spin {
  to { transform: rotate(360deg); }
}
.sp-spin {
  animation: sp-spin 0.8s linear infinite;
}

sp_widget.script:
(function() {
  data.message = '';
  data.success = false;
  data.netsRecord = null;
  data.formSaved = false;

  try {
    if (input && input.action === 'searchNets') {
      var gr = new GlideRecord('x_1643968_bell_f_0_bell_flash');
      gr.addQuery('nets_number', input.nets_number);
      gr.setLimit(1);
      gr.query();
      if (gr.next()) {
        data.netsRecord = {
          sys_id: gr.getUniqueValue(),
          number: gr.getValue('number') + '',
          short_description: gr.getValue('short_description') + '',
          flash_type: gr.getDisplayValue('flash_type') + '',
          flash_status: gr.getDisplayValue('flash_status') + '',
          severity: gr.getDisplayValue('severity') + '',
          notification_message: gr.getValue('notification_message') + '',
          nets_number: gr.getValue('nets_number') + '',
          recipient_group: gr.getDisplayValue('recipient_group') + '',
          recipient_user: gr.getDisplayValue('recipient_user') + '',
          sys_created_on: gr.getDisplayValue('sys_created_on') + ''
        };
        data.success = true;
      } else {
        data.message = 'No flash record found for NETS number: ' + input.nets_number;
        data.success = false;
      }
      return;
    }

    if (input && input.action === 'saveGeneral') {
      var newGr = new GlideRecord('x_1643968_bell_f_0_bell_flash');
      newGr.initialize();
      newGr.setValue('short_description', input.short_description || '');
      newGr.setValue('notification_message', input.notification_message || '');
      newGr.setValue('severity', input.severity || 'medium');
      newGr.setValue('flash_type', 'general');
      newGr.setValue('flash_status', input.flash_status || 'draft');
      if (input.recipient_group) {
        newGr.setValue('recipient_group', input.recipient_group);
      }
      if (input.recipient_user) {
        newGr.setValue('recipient_user', input.recipient_user);
      }
      var id = newGr.insert();
      if (id) {
        data.success = true;
        data.formSaved = true;
        data.message = newGr.getValue('number') + ' created successfully with status: ' + input.flash_status;
      } else {
        data.success = false;
        data.message = 'Failed to create flash record.';
      }
      return;
    }
  } catch (e) {
    gs.error('bf_nnoc_main error: ' + e.message);
    data.message = 'An error occurred: ' + e.message;
  }
})();
